import { mock } from 'node:test';
import path from 'node:path';
const fs = await import('node:fs/promises');
const root = await fs.realpath(await fs.mkdtemp('/tmp/ship-choosing-cleanup-'));
const claim = path.join(root, 'state.json');
let fault = true;
let ran1 = false;
let ran2 = false;
const results = { root, pid: process.pid };
mock.module('node:fs/promises', { namedExports: { ...fs,
  mkdir: async (p, ...args) => {
    const value = await fs.mkdir(p, ...args);
    if (fault && String(p).startsWith(root) && String(p).includes('.pubq-')) {
      fault = false;
      await fs.chmod(root, 0o555);
    }
    return value;
  },
} });
const { withPublishMutex } = await import('/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/lock-pubmutex.js');
try {
  await withPublishMutex(claim, claim, () => false, async () => { ran1 = true; }).catch(e => { results.firstError = { message:e.message, code:e.code }; });
  results.firstRan = ran1;
  await fs.chmod(root, 0o755);
  results.afterRestore = await fs.readdir(root);
  const start = Date.now();
  await withPublishMutex(claim, claim, () => Date.now() - start >= 250, async () => { ran2 = true; }).catch(e => { results.secondError = e.message; });
  results.secondElapsed = Date.now() - start;
  results.secondRan = ran2;
  results.afterSecond = await fs.readdir(root);
  await fs.writeFile('/tmp/codex-tool-runs/svton/choosing-final-20261004/choosing-cleanup-result.json', JSON.stringify(results, null, 2));
  console.log(JSON.stringify(results, null, 2));
  if (!results.secondRan || results.afterSecond.length) throw Error('Recovery or marker cleanup invariant failed');
} finally {
  await fs.chmod(root, 0o755).catch(()=>{});
  await fs.rm(root, { recursive: true, force: true });
}

import assert from 'node:assert/strict';
import { mock } from 'node:test';
import { createServer } from 'node:net';
import { createHash } from 'node:crypto';
import * as realfs from 'node:fs/promises';
import path from 'node:path';

const sourceRoot = '/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit';
const output = '/tmp/codex-tool-runs/svton/shipkit-discover-live-review/result.json';
const root = await realfs.realpath(await realfs.mkdtemp('/tmp/ship-discovery-review-'));
const registry = path.join(root, 'registry');
await realfs.mkdir(registry);
const file = path.join(root, 'state.json');
await realfs.writeFile(file, '0');
const fixed = '/var/tmp/shipkit-lock-ports';
const map = (p) => String(p).startsWith(fixed) ? registry + String(p).slice(fixed.length) : p;
mock.module('node:fs/promises', { namedExports: { ...realfs,
  mkdir: (p, ...args) => realfs.mkdir(map(p), ...args),
  readdir: (p, ...args) => realfs.readdir(map(p), ...args),
  readFile: (p, ...args) => realfs.readFile(map(p), ...args),
  writeFile: (p, ...args) => realfs.writeFile(map(p), ...args),
  rename: (a, b, ...args) => realfs.rename(map(a), map(b), ...args),
  rm: (p, ...args) => realfs.rm(map(p), ...args),
  access: (p, ...args) => realfs.access(map(p), ...args),
} });
const { withFileLock, lockKeyOf } = await import(`${sourceRoot}/dist/shared/file-lock.js`);
const key = lockKeyOf(file);
const hash = createHash('sha256').update(key).digest('hex');
const claim = path.join(registry, `${hash.slice(0, 20)}.json`);
const firstPort = 49152 + createHash('sha256').update(`${key}\u00000`).digest().readUInt32BE(0) % 16383;
const sockets = new Set();
const silent = createServer((socket) => { sockets.add(socket); socket.once('close', () => sockets.delete(socket)); });
let release;
let holder;
let active = 0;
let maxActive = 0;
let enteredResolve;
const entered = new Promise((r) => { enteredResolve = r; });
const result = { case: 'unidentifiable early candidate then live same-key later candidate', root, key, firstPort };
const killTimer = setTimeout(() => { process.stderr.write('review watchdog expired\n'); process.exit(2); }, 10000);
try {
  await new Promise((resolve, reject) => { silent.once('error', reject); silent.listen(firstPort, '127.0.0.1', resolve); });
  holder = withFileLock(file, async () => {
    active++; maxActive = Math.max(maxActive, active);
    enteredResolve();
    try { await new Promise((r) => { release = r; }); await realfs.writeFile(file, '1'); }
    finally { active--; }
  }, { timeoutMs: 2500 });
  await Promise.race([entered, holder]);
  assert.equal(active, 1);
  const initial = JSON.parse(await realfs.readFile(claim, 'utf8'));
  result.livePort = initial.port;
  assert.notEqual(initial.port, firstPort, 'holder uses a later candidate');
  await realfs.writeFile(claim, '{torn');
  let contenderRan = false;
  const t0 = Date.now();
  try {
    await withFileLock(file, async () => {
      contenderRan = true; active++; maxActive = Math.max(maxActive, active); active--;
    }, { timeoutMs: 1500 });
    result.contenderOutcome = 'success';
  } catch (e) { result.contenderOutcome = 'timeout'; result.contenderError = String(e.message); }
  result.contenderElapsedMs = Date.now() - t0;
  result.contenderRan = contenderRan;
  result.repairedPort = JSON.parse(await realfs.readFile(claim, 'utf8')).port;
  assert.equal(result.repairedPort, initial.port, 'repair converges to the later live holder');
  assert.equal(contenderRan, false, 'contender never enters during live holder');
  assert.equal(result.contenderOutcome, 'timeout');
  assert.match(result.contenderError, /超时/);
  assert.equal(active, 1);
  release(); await holder;
  let laterRan = false;
  await withFileLock(file, async () => {
    laterRan = true; active++; maxActive = Math.max(maxActive, active);
    try { const old = Number(await realfs.readFile(file, 'utf8')); await realfs.writeFile(file, String(old + 1)); }
    finally { active--; }
  }, { timeoutMs: 1000 });
  result.laterRan = laterRan;
  result.maxActive = maxActive;
  result.finalValue = Number(await realfs.readFile(file, 'utf8'));
  result.finalPort = JSON.parse(await realfs.readFile(claim, 'utf8')).port;
  result.markerResidue = (await realfs.readdir(registry)).filter((n) => n.includes('.pub') || n.endsWith('.tmp'));
  assert.equal(laterRan, true); assert.equal(maxActive, 1); assert.equal(result.finalValue, 2);
  assert.equal(result.finalPort, initial.port); assert.deepEqual(result.markerResidue, []);
  result.passed = true;
} catch (e) { result.passed = false; result.error = e.stack; process.exitCode = 1; }
finally {
  release?.(); await holder?.catch(() => {});
  for (const socket of sockets) socket.destroy();
  if (silent.listening) await new Promise((r) => silent.close(r));
  await realfs.rm(root, { recursive: true, force: true });
  result.cleaned = true;
  result.sourceHashes = {};
  for (const filename of ['lock-registry.ts', 'lock-pubmutex.ts', 'file-lock.ts']) {
    result.sourceHashes[filename] = createHash('sha256').update(await realfs.readFile(`${sourceRoot}/src/shared/${filename}`)).digest('hex');
  }
  await realfs.writeFile(output, JSON.stringify(result, null, 2) + '\n');
  process.stdout.write(JSON.stringify(result) + '\n');
  clearTimeout(killTimer);
}
